<?php $pageTitle='Teams'; require 'config.php'; require 'includes/functions.php'; require_role('student');$uid=user()['id'];$role=user()['role'];
if($_SERVER['REQUEST_METHOD']==='POST' && $role==='team_leader'){ $stmt=$pdo->prepare('INSERT INTO teams(leader_id,name,hackathon_name,description,max_size,roles_needed,skills_required) VALUES(?,?,?,?,?,?,?)');$stmt->execute([$uid,trim($_POST['name']),trim($_POST['hackathon_name']),trim($_POST['description']),(int)$_POST['max_size'],trim($_POST['roles_needed']),trim($_POST['skills_required'])]);$tid=$pdo->lastInsertId();$pdo->prepare("INSERT INTO team_members(team_id,user_id,member_role,status) VALUES(?,?,?,?)")->execute([$tid,$uid,'Leader','active']);flash('success','Team created.');header('Location: teams.php');exit;}
if(isset($_GET['join']) && $role==='student'){ $tid=(int)$_GET['join'];$stmt=$pdo->prepare('INSERT IGNORE INTO team_join_requests(team_id,user_id,status) VALUES(?,?,?)');$stmt->execute([$tid,$uid,'pending']);flash('success','Join request sent.');header('Location: teams.php');exit;}
$teams=$pdo->query("SELECT t.*,u.name leader_name,(SELECT COUNT(*) FROM team_members tm WHERE tm.team_id=t.id AND tm.status='active') member_count FROM teams t JOIN users u ON u.id=t.leader_id ORDER BY t.created_at DESC")->fetchAll();include 'includes/header.php';?>
<?php if($role==='team_leader'):?><div class="card"><h2>Create Hackathon Team</h2><form method="post"><div class="grid two"><div class="form-group"><label>Team Name</label><input name="name" required></div><div class="form-group"><label>Hackathon</label><input name="hackathon_name" required></div><div class="form-group"><label>Maximum Team Size</label><input type="number" min="2" max="20" name="max_size" value="4"></div><div class="form-group"><label>Roles Needed</label><input name="roles_needed" placeholder="Frontend, ML, Designer"></div></div><div class="form-group"><label>Skills Required</label><input name="skills_required"></div><div class="form-group"><label>Description</label><textarea name="description"></textarea></div><button class="btn">Create Team</button></form></div><?php endif;?>
<h2 class="section-title">Team Directory</h2><div class="grid"><?php foreach($teams as $t):?><div class="card"><span class="badge"><?=e($t['member_count'])?> / <?=e($t['max_size'])?> members</span><h3><?=e($t['name'])?></h3><p class="muted"><?=e($t['hackathon_name'])?> • <?=e($t['leader_name'])?></p><p><?=e($t['description'])?></p><p><b>Needs:</b> <?=e($t['skills_required']?:'Open')?></p><?php if($role==='student'):?><a class="btn" href="teams.php?join=<?=$t['id']?>">Request to Join</a><?php endif;?></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
